-- Migration 0044_adapter_framework: generated by drizzle-kit (enums, tables, keys, indexes), RLS, the view and grants hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #372)
-- Court-adapter versioning and parse health (#372, part 4 of #35; ADR 0015):
--   * adapter_version: global (GLOBAL_TABLES), no RLS. One row per (adapter, semver) with the
--     validated config, its sha256 checksum and the digest of the golden fixtures it passed. The
--     partial unique index adapter_version_one_active_uq allows exactly one 'active' row per
--     adapter. Staff manage it through the app role (SELECT, INSERT, UPDATE), like
--     access_mode_registry (0012); the clerk role has no privileges on it.
--   * adapter_parse_run: tenant table (tenantTable()) under FORCE RLS with ws_isolation
--     (tenantPolicy()). Metrics only (counts and hall numbers), never row text. Rows cascade with
--     their document and workspace.
--   * owner_definer_read on adapter_parse_run lets only the owner read it across workspaces, so
--     the owner-owned view adapter_health_summary (a view runs with its owner's rights) can
--     aggregate every workspace. The view groups by adapter and version only and exposes counts:
--     no workspace, document or hall. The app and clerk roles may only SELECT it.
-- Expand only: new enums, tables, a policy and a view.
CREATE TYPE "public"."adapter_version_status" AS ENUM('draft', 'active', 'retired');--> statement-breakpoint
CREATE TYPE "public"."parse_health_status" AS ENUM('ok', 'degraded', 'failed');--> statement-breakpoint
CREATE TABLE "adapter_parse_run" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"document_id" uuid NOT NULL,
	"adapter_id" text NOT NULL,
	"adapter_version" text NOT NULL,
	"forum_code" text NOT NULL,
	"rows_parsed" integer NOT NULL,
	"rows_anchored" integer NOT NULL,
	"unmapped_headings" integer NOT NULL,
	"unknown_case_types" integer NOT NULL,
	"halls_seen" text[] DEFAULT '{}'::text[] NOT NULL,
	"halls_unreadable" text[] DEFAULT '{}'::text[] NOT NULL,
	"status" "parse_health_status" NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "adapter_parse_run_counts_chk" CHECK (rows_parsed >= 0 and rows_anchored >= 0 and rows_anchored <= rows_parsed and unmapped_headings >= 0 and unknown_case_types >= 0)
);
--> statement-breakpoint
CREATE TABLE "adapter_version" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"adapter_id" text NOT NULL,
	"version" text NOT NULL,
	"config" jsonb NOT NULL,
	"status" "adapter_version_status" DEFAULT 'draft' NOT NULL,
	"checksum" text NOT NULL,
	"fixtures_digest" text,
	"activated_at" timestamp with time zone,
	"activated_by" uuid,
	"last_verified_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "adapter_version_adapter_version_uq" UNIQUE("adapter_id","version"),
	CONSTRAINT "adapter_version_adapter_id_chk" CHECK (adapter_id ~ '^[a-z][a-z0-9-]*$'),
	CONSTRAINT "adapter_version_semver_chk" CHECK (version ~ '^[0-9]+\.[0-9]+\.[0-9]+$'),
	CONSTRAINT "adapter_version_checksum_chk" CHECK (checksum ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "adapter_version_fixtures_digest_chk" CHECK (fixtures_digest is null or fixtures_digest ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "adapter_version_active_chk" CHECK (status <> 'active' or activated_at is not null)
);
--> statement-breakpoint
ALTER TABLE "adapter_parse_run" ADD CONSTRAINT "adapter_parse_run_workspace_id_fk" FOREIGN KEY ("workspace_id") REFERENCES "public"."organization"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "adapter_parse_run" ADD CONSTRAINT "adapter_parse_run_document_fk" FOREIGN KEY ("workspace_id","document_id") REFERENCES "public"."document"("workspace_id","id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "adapter_version" ADD CONSTRAINT "adapter_version_activated_by_user_id_fk" FOREIGN KEY ("activated_by") REFERENCES "public"."user"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "adapter_parse_run_workspace_id_idx" ON "adapter_parse_run" USING btree ("workspace_id");--> statement-breakpoint
CREATE INDEX "adapter_parse_run_workspace_forum_idx" ON "adapter_parse_run" USING btree ("workspace_id","forum_code","created_at");--> statement-breakpoint
CREATE UNIQUE INDEX "adapter_version_one_active_uq" ON "adapter_version" USING btree ("adapter_id") WHERE status = 'active';--> statement-breakpoint
ALTER TABLE "adapter_parse_run" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "adapter_parse_run" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "ws_isolation" ON "adapter_parse_run" AS PERMISSIVE FOR ALL TO PUBLIC USING (workspace_id = nullif(current_setting('app.workspace_id', true), '')::uuid) WITH CHECK (workspace_id = nullif(current_setting('app.workspace_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "owner_definer_read" ON "adapter_parse_run" AS PERMISSIVE FOR SELECT TO causedeck_owner
  USING (true);--> statement-breakpoint
CREATE VIEW "adapter_health_summary" AS
  SELECT r.adapter_id,
         r.adapter_version,
         count(*) AS runs,
         count(*) FILTER (WHERE r.status = 'ok') AS ok_runs,
         count(*) FILTER (WHERE r.status = 'degraded') AS degraded_runs,
         count(*) FILTER (WHERE r.status = 'failed') AS failed_runs,
         coalesce(sum(r.rows_parsed), 0)::bigint AS rows_parsed,
         coalesce(sum(r.rows_anchored), 0)::bigint AS rows_anchored
    FROM adapter_parse_run r
   GROUP BY r.adapter_id, r.adapter_version;--> statement-breakpoint
REVOKE ALL ON "adapter_health_summary" FROM PUBLIC, causedeck_app, causedeck_clerk;--> statement-breakpoint
GRANT SELECT ON "adapter_health_summary" TO causedeck_app, causedeck_clerk;--> statement-breakpoint
REVOKE ALL ON "adapter_version" FROM PUBLIC, causedeck_app, causedeck_clerk;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "adapter_version" TO causedeck_app;
